import { AuthOptions } from "../route/auth-options.js";
import { MediaRoute } from "../route/media.js";
import { ProviderID } from "../schema/index.js";
import { ReplicateImages } from "../protocols/replicate-images.js";
export const id = ProviderID.make("replicate");
const auth = (options) => AuthOptions.bearer(options, "REPLICATE_API_TOKEN");
export const configure = (input = {}) => {
    const media = MediaRoute.deployment(input, auth(input));
    const image = (modelID) => ReplicateImages.model({ ...media, id: modelID });
    return {
        id,
        image,
        configure,
    };
};
export const provider = configure();
export const image = provider.image;
